INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Барои фермерони Тоҷикистон: Чӣ тавр бо истифода аз нафари Tip ҳосили салатро дар ҳар ҳектар бартарӣ диҳед. Маълумотҳои амалӣ ҳақи техникаи наварӣ (Tip). Инчунин маълумотро аз AFP ба даст овардан мумкин аст.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
