INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','تعرف على الطرق الفعالة لإدارة الآفات والأمراض في محاصيل الخضروات باستخدام نظام الري بالتنقيط، مع نصائح عملية للمزارعين العراقيين لزيادة المحصول والحد من المكافحة الكيميائية.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
