INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Бо истифода аз технологияи намоишдиҳӣ ҳашорот ва бемориҳои сабзавотро бо роҳи муосир идора кунед ва ҳосилро беҳтар созед. Ин раҳнамӯз ба тартиботи амалии кӯмак мерасонед.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
