INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','تعرف على الخطوات الفنية الأساسية لتطبيق تصحيح ملون مع شريط TIP لتحقيق أقصى كفاءة في نظام الري بالتنقيط، مع توجيهات عملية مخصصة للمزارعين لتحسين استهلاك المياه وزيادة الإنتاجية.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
