INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқадима дар бораи аҳамияти нигоҳубини тарбузи чубукӣ бо ленти капта</h2>\n<p>Кишт тарбуз яке аз мураккабтарин самтҳо дар деҳқонӣ мебошад, зеро ин намуди ғаланбе ба тағйирот дар намӣи хок хеле ҳассос аст. Ҷиҳати истифодаи <strong>ленти капта</strong> дар ороғи нақтӣ метавонад дорунаҳои рушди тарбузро бо дақиқӣ ва самаранокии баланд иҷро кунад, аммо камолӣ дар ин усул ба риояи қоидаҳои дақиқи нигоҳубин вобаста аст. Бисёр деҳқонҳо, гарчанде ки ба мӯҳрасибонии барои таҷҳизот анҷом додаанд, бевобастаги ба бандҳои хурди нигоҳубин, бо камбудии самаранокӣ ва ҳузуру баромади таъмир мусоидат мекунанд.</p>\n<p>Ҳади ин мақола пешниҳоди як нақшаи роҳи амалӣ барои идоракунии ва нигоҳубини системаи ленти капта дар боғзорҳои тарбуз аст. Мо бар асоси таҷрибаи техникӣ ва принсипҳои гидравликӣ, ба таҳлили чӣ гуна сунукшавии байни хок, даҳшакорӣ ва таҷҳизоти ороғӣ мерасем, то ки деҳқонҳо метавонанд доимии самаранокии ғаланберо таъмин кунанд.</p>\n\n<h2>Таъсири даҳшакории замин ба кори ленти капта дар боғзорҳои тарбуз</h2>\n<p>Параметри даҳшакории замин яке аз муҳимтарин омили таҳия ва нигоҳубини системаи ороғи ленти капта мебошад. Тарбуз бо сабаби андозаҳои ниҳони бешумора дар замин, ба тақсимоти яхмои оби дар тӯли лент ниёз дорад. Агар даҳшакории замонӣ мувофиқ барои ҷараёни об набошад, метавонад дар поёни ҳароратӣ, тақсимоти об бо сабаби падидаҳои гидравликӣ кам шавад ё ақиб, пуршавии об (силовшавӣ) рух диҳад.</p>\n<a href="https://navar-abyari.ir/%D8%B4%D8%B1%D9%8A%D8%B7-%D8%A7%D9%84%D8%B1%D9%8A-%D8%A8%D8%A7%D9%84%D8%AA%D9%86%D9%82%D9%8A%D8%B7-%D9%81%D9%8A-%D8%A8%D8%B5%D8%B1%D9%87/">Ҳолатҳои иқлимии мувофиқ дар Башир</a> ва минтақаҳои монанд ба он, одатан даҳшакориҳои нарм ё сатҳҳои якхела доранд, ки барои кишт тарбуз идеял мебошанд. Аммо, ҳатто дар сатҳҳои пӯришор, бояд аз ҳасири дақиқ барои кӯҳҳои тарбуз истифода бурд, то ки ҷараёни об дар система ба таври якхела паҳн шавад. Вобастаги ба ин муҳимӣ метавонад боиси тақсимоти об дар қисмати боло (омаккашӣ) ва хушкӣ дар поён (пастинӣ) система гардад, ки бевобастаги ба вазн ва боии меволаро тарбуз таъсири манфӣ мекунад.</p>\n\n[{{{IMAGE_1}}}]</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-ملون-با-نوار-تیپ-نکات-کلیدی-تصویر-شاخص.webp" alt="نگهداری ملون با نوار تیپ: نکات کلیدی - تصویر 1"/><figcaption>crop drip tape maintenance care тарбуз</figcaption></figure>\n\n<h2>Нақши филтркуниро дар пешгирии пуршавии ленти капта</h2>\n<p>Яке аз мушкилоти маъмултарин дар нигоҳубини тарбуз бо ленти капта, пуршавии чуқури майи лент аст. Тарбуз одатан дар саҳобҳои тӯлокаю тӯлокашӣ кишт мешавад ва ин сохтор имконияти ҷойгиршавии ленти капта бо осонӣ дар тӯли ниҳошӣро фароҳам меорад. Аммо агар об дорои қабҳои мисқадони қабзӣ, ашмоӣ ё ҳатто ҳашорот бошад, ин қабҳо дар нуқтаҳои танги лент ҷамъ шуда ҷараёнро хомеш мекунад.</p>\n<h3>Интихоби системаи филтр мувофиқ</h3>\n<ul>\n<li><strong>Филтри металлӣ:</strong> Дар манбаи оби паст-рағбатнокӣ ва қабҳои минералӣ, филтри металлӣ бо тарҳи 100 то 200 мувофиқ аст. Ин филтрҳо барои тарбуз, ки ҳассоси баланд ба дараҷаи мусаббатнокӣ дорад, дар ҳолатҳои муқаррабӣ истифода мешавад.</li>\n<li><strong>Филтри дискӣ (сплит):</strong> Барои манбаҳои оби дорои қабҳои ашмоӣ, филтрҳои дискӣ (дискӣ) таври беҳтар мебошанд. Ин филтрҳо сатҳи нисбаи калонтарро барои шустушув доранд ва метавонанд қабҳои майиро бо самаранокӣ филтр кунанд.</li>\n</ul>\n<p>Нуқтаи муҳимтарин дар нигоҳубин, шустушуви мунтазами филтрҳо аст. Бо вобастаги ба ин ки тарбуз ба тағозаи давомноки ниёз дорад, вазеши системаи ороғ бо сабаби пуршавии филтр метавонад боиси дарандозии меваҳои навовул ва паст шудани сифати маҳсулот гардад. Деҳқонҳо бояд пеш аз ҳар даураи ороғ, сатҳи филтро санҷиш диҳанд.</p>\n\n<h2>Идоракунии фишори об дар системаи нӯрии қутъарезӣ</h2>\n<p>Барои корпаштани хурма фишори муносиби об дар нӯри қутъарезӣ бояд дар диапазони аз 1.5 то 3 бар нигоҳ дошта шавад. Фишори баландтар аз 3 бар метавонад боиси вайроншавии қутъа, паршонии беконтроли об ва парокшидани заррачаҳои нозук дар хок гардад. Фишори пасттар аз 1.5 бар низ боиси паҳн намудани нокомии об ва хушкшавии решаҳои чуқури хурма мегардад. Барои нигоҳ доштани фишори устувор, истифодаи регулятори фишор ва насб кардани он дар охири хати асосӣ тавсия дода мешавад.</p>\n<p>Ҳамчунин, диққат ба камшавии фишор дар хатҳои интиқолӣ зарур аст. Бо дарозтар шудани хатҳо, фишор дар охири хатҳо кам мегардад. Бинобар ин, дар боғҳои калони хурма хатҳо бояд бо таври параллелӣ ё бо тақсимоти мувофиқ ба назар гирифта шаванд, то якхилӣ дар тамоми боғ таъмин гардад. Барои маълумоти бештар дар бораи роҳи ҳисоб кардани ин параметрҳо, шумо метавонед ба <a href="https://navar-abyari.ir/kudwa-natiq-iq-production-per-hectare-drip-tape/">Масъалаи истеҳсоли нӯри қутъарезӣ барои ҳар гектар хурма</a> ки ба таҳлили самаранокии системаҳои нӯри қутъарезӣ ишора мекунад, муроҷиат кунед.</p>\n\n[{{{IMAGE_2}}}]</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-ملون-با-نوار-تیپ-نکات-کلیدی-کاربرد-عملی.webp" alt="نگهداری ملون با نوار تیپ: نکات کلیدی - تصویر 2"/><figcaption>Нигоҳдории нӯри қутъарезӣ барои хурма ва эҳтиёт</figcaption></figure>\n\n<h2>Нуктаҳои амалӣ барои зиёд кардани умри нӯри қутъарезӣ дар корпаштани хурма</h2>\n<p>Корпаштани хурма аксар вақт бо таври якдараҷа (як мавсимӣ) сурат мегирад, яъне пас аз ҷамъоварии маҳсулот, системаи нӯри қутъарезӣ бояд аз хок хориҷ карда шавад ё омодагӣ барои корпашти оянда анҷом дода шавад. Дар бисёр системаҳои муосир, нӯри қутъарезии якмаротиба ё бо давомнокии қобили диққат тарҳрезӣ шудаанд. Барои беҳтар кардан, нуктаҳои зерро ба назар гиред:</p>\n<ol>\n<li><strong>Баргардонидан ба истифода:</strong> Агар нӯри қутъарезӣ озоди механикии баланд дошта бошад ва ба он зарба расида набошад, шумо метавонед онро оҳиста аз хок хориҷ кунед ва барои корпашти оянда истифода баред. Ин кор бояд бо эҳтиёт иҷро шавад, то сӯрохиҳои қутъа васеъ ё пӯшида набошанд.</li>\n<li><strong>Поксозии хатҳо:</strong> Пас аз охир расидани сайқли истеҳсоли хурма, системаро бо маҳлулги кислотӣ (масалан, кислотаи лимонӣ ё хлориди кислотаи реقيқ) аз дохил шустушӯ кунед, то арақҳои органикӣ ва معدнии аз деворҳо паст кунанд. Ин кор умри нӯри қутъарезиро ба таври зоҳирӣ зиёд мекунад.</li>\n<li><strong>Нигоҳдори дар шароити мувофиқ:</strong> Нӯри қутъарезии истифодашуда бояд дар ҷои торик, хунук ва бе тамос бо моддаҳои кимиёвӣ нигоҳ дошта шаванд. Нури мустақими офтоб боиси паст кардани сифати полиэтилен ва сахт шудани он мегардад.</li>\n</ol>\n<p>Барои роҳнамоии дақиқтар дар бораи миқдори самаранокии ҳар гектар бо ба назар гирифтани фосилаи нӯриҳо, муроҷиат ба <a href="https://navar-abyari.ir/mikyori-hosili-marza-dar-yek-gektar-rahnamoi-purra/">Микроскопии маҳсулоти маржа дар як гектар роҳнамояи пурра</a> тавсия дода мешавад. Ин манбаъҳо метавонанд кӯмак кунанд, то зичии мувофиқи хурма мувофиқи системаи обёрӣ танзим карда шавад.</p>\n\n<h2>Ҷавоб ба саволҳои мушкилӣ дар бораи нигоҳдории нӯри қутъарезӣ дар корпаштани хурма</h2>\n<div style="margin-bottom: 20px;">\n<h3>Оё нӯри чизпа барои тамоми навъҳои тарбуза мувофиқ аст?</h3>\n<p>Бале, нӯри чизпа бо сабаби имконияти тақсимоти дақиқи об дар решаҳои сатҳӣ, барои аксари навъҳои тарбуза мувофиқ аст. Аммо навъҳое, ки ҳассосияти баланд доранд, шояд ба хатҳои бештар ё фосилаи наздиктарин байни хатҳо ниёз дошта бошанд.</p>\n</div>\n<div style="margin-bottom: 20px;">\n<h3>Беҳтарин вақт барои шустани системаи нӯри чизпа кай аст?</h3>\n<p>Беҳтарин вақт, пас аз анҷоми даври ҳосилбардории тарбуза ва пеш аз оғози мавсими оянда аст. Шустани дохилӣ бо кислота ва берунӣ бо ҳалли муқобилбарои микробҳо, умри системаро нигоҳ медорад.</p>\n</div>\n<div style="margin-bottom: 20px;">\n<h3>Чӣ тавр метавонам гирифтории нӯри чизпоро муайян кунам?</h3>\n<p>Бо камшавии фишор дар охирҳои хатҳо, ноҳоми хориши об аз нӯрҳо ва мушоҳидаи афкоришуда дар атрофи нуқтаҳои хориш. Агар дар як қисми нӯр, оби хориш кам шуда ва қисми дигари он нарм бошад, эҳтимоли гирифторӣ вуҷуд дорад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-ملون-با-نوار-تیپ-نکات-کلیدی-جزئیات-فنی.webp" alt="نگهداری ملون با نوار تیپ: نکات کلیدی - تصویر 3"/><figcaption>crop drip tape maintenance care тарбуза</figcaption></figure>\n</div>\n<div style="margin-bottom: 20px;">\n<h3>Оё истифодаи нӯри чизпа барои тарбуза дар хокҳои камобӣ тавсия дода мешавад?</h3>\n<p>Дар хокҳои обрав, нӯри чизпа метавонад обро бевосита ба минтақаи решаҳо равона кунад, аммо ба диққати махсус дар танзими филтратсия ниёз дорад. Тавсия дода мешавад, ки ба миқдори истифодаи раъҷ дар як гектар диққат диҳед, то зичии решаҳоро бо қобилияти таъмини об ода система мувофиқ кунед.</p>\n</div>\n\n<h2>Хулоса ва тавсияҳои ниҳоӣ</h2>\n<p>Нигоҳдории тарбуза бо нӯри чизпа ба дақиқӣ дар ҷузъиёти ниёз дорад. Аз назорати шидати замин ва интихоби филтри мувофиқ то фишори мувофиқи система ва тозакунии мунтазам, ҳар яки ин омилҳо ба беҳтар шудани самаранокии иқтисодиёти боғи тарбуза мусоидат мекунанд. Бо пайравӣ ба ин нуқтаҳои асосӣ, деҳқонон метавонанд аз фоидаҳои обёрӣ дар нӯрҳо истифода баранд ва ҳамзамон, ҳаҷмҳои таъмиротӣ ва сарфи энергияро кам намоянд.</p>\n<p>Барои ошноӣ бо роҳҳои оптимизатсияи обёрӣ дар маҳсулоти дигар, шумо метавонед ба <a href="https://navar-abyari.ir/pomidor-support-tape-guide/">раҳнамоии нӯри дастгирии гӯшт</a> муроҷиат кунед. Чӣ қадар дониши фаннии шумо дар бораи системаҳои обёрӣ дақиқтар бошад, қудрати муайян кардан ва пешгирии вайроншавӣ дар боғҳои тарбуза бештар хоҳад буд. Сармоягузорӣ дар нигоҳдории нӯри чизпа, дар натиҷа ба самаранокии баланди маҳсулот бо сифати беҳтар мусоидат мекунад.</p>\n\n[{{{IMAGE_3}}}]</p>','Нигоҳубини зарраҳо бо стринги Т-шакл: нуқтаҳои асосӣ барои беҳтар кардани ороғи мондаро','Нигоҳдории дурусти молон бо навари тик (tip) боиси афзоиши самаранокӣ ва кам кардани сарфаҳои обёрӣ мегардад. Ин дастур саммити махсусро дар бораи танзими шомол, филтратсия ва эҳтиётот аз система дар бар мегирад.','publish','closed','closed','nigohubini-tila-ba-stringi-t-shakl-oarozi-monandor',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
