INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Дар ин мақола мо роҳҳои дурусти нигоҳубини зарраҳоро бо истифода аз стринги Т-шакл баррасӣ мекунем. Оё шумо кӯшиши беҳтар кардани самаранокӣ ва самаранокии ороғи мондаро дар боғоният доред? Инҳо нуқтаҳои асосии техникӣ ва машваратҳои AFP барои сатҳ баланди нигоҳубин.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
